<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Password recovery</title></head>
<body style="margin:0;padding:0;background:#f5f7fb;color:#20283a;font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f5f7fb"><tr><td align="center" style="padding:48px 16px">
        <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:540px">
            <tr><td align="center" style="padding:0 0 18px"><table role="presentation" cellspacing="0" cellpadding="0"><tr><td style="width:34px;height:34px;border-radius:11px;background:#5b6cfa;color:#fff;text-align:center;vertical-align:middle;font-size:17px;font-weight:700">P</td><td style="padding-left:9px;color:#20283a;font-size:18px;font-weight:700;letter-spacing:-.5px">Planora</td></tr></table></td></tr>
            <tr><td style="overflow:hidden;border:1px solid #e6eaf2;border-radius:20px;background:#fff;box-shadow:0 16px 42px rgba(32,40,58,.08)"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">
                <tr><td style="padding:36px 38px 12px"><p style="margin:0 0 10px;color:#5b6cfa;font-size:10px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase">Account security</p><h1 style="margin:0;color:#20283a;font-size:25px;line-height:1.25;letter-spacing:-.6px">Reset your password</h1><p style="margin:13px 0 0;color:#748096;font-size:14px;line-height:1.7">We received a request to reset your Planora password. Enter this one-time code to continue. It expires in <strong style="color:#20283a">5 minutes</strong>.</p></td></tr>
                <tr><td align="center" style="padding:25px 24px 27px"><table role="presentation" cellspacing="0" cellpadding="0"><tr><td style="padding:16px 22px;border:1px solid #e3e7ff;border-radius:13px;background:#f5f6ff;color:#3445c4;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:31px;font-weight:700;letter-spacing:9px">{{ $code }}</td></tr></table></td></tr>
                <tr><td style="padding:0 38px 34px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td style="padding:13px 15px;border:1px solid #e6eaf2;border-radius:11px;background:#fafbfe;color:#8490a5;font-size:11px;line-height:1.65"><strong style="color:#4f5a70">Never share this code.</strong> Planora will never ask you to share it. If you did not request a password reset, you can safely ignore this message; your password will remain unchanged.</td></tr></table></td></tr>
            </table></td></tr><tr><td align="center" style="padding:18px 10px 0;color:#9aa3b2;font-size:10px;line-height:1.6">A calmer way to plan your work.<br>© Planora</td></tr>
        </table>
    </td></tr></table>
</body></html>
